import {canonicalMoveId} from './teamcraft-data.js?v=0.90.40';
export function maximumPP(unit,move){const n=Number(unit.ppBonusByMoveId?.[move.id]||0);return move.pp+(Number.isSafeInteger(n)&&n>0?n:0);}
export function redirectInheritance(record){if(record&&Number.isInteger(record.moveId)){const id=canonicalMoveId(record.moveId);if(id!==record.moveId){record.moveId=id;record.teamcraftAliasMigration=true;}}}
export function normalizeTeamcraftUnit(u,moves){redirectInheritance(u.breedingInheritance);const by=new Map(moves.map(m=>[m.id,m])),bonus={};for(const [key,value]of Object.entries(u.ppBonusByMoveId||{})){if(Number.isSafeInteger(value)&&value>0){const id=canonicalMoveId(key);bonus[id]=Math.max(bonus[id]||0,value);}}u.ppBonusByMoveId=bonus;const unique=new Map();
 for(const old of u.moves||[]){let id=canonicalMoveId(old.id);if(id===470&&old.category==='SPECIAL')id=710;const base=by.get(id);if(!base)continue;const pp=maximumPP(u,base),m={...base,basePP:base.pp,pp,left:Math.max(0,Math.min(pp,Number.isFinite(old.left)?old.left:base.pp))};if(!unique.has(id))unique.set(id,m);else{unique.get(id).left=Math.min(unique.get(id).left,m.left);u.freeMoveChoice=true;}}
 u.moves=[...unique.values()];u.teamcraftVersion=1;return u;
}
export function tonicQuote(state,u,id,count=1){id=canonicalMoveId(id);const n=u?.ppBonusByMoveId?.[id]||0;let cost=0;if(!u||u.dead||u.hp<=0||!u.moves.some(m=>m.id===id)||!Number.isSafeInteger(count)||count<1||count>10000)return {ok:false,cost:0};for(let i=1;i<=count;i++){cost+=1000*(n+i)**2;if(!Number.isSafeInteger(cost))return {ok:false,cost:0};}return {ok:state.money>=cost&&Number.isSafeInteger(n+count),cost,count,id};}
export function buyPPTonic(state,u,id,count=1){const q=tonicQuote(state,u,id,count);if(!q.ok)return false;u.ppBonusByMoveId??={};u.ppBonusByMoveId[q.id]=(u.ppBonusByMoveId[q.id]||0)+count;const m=u.moves.find(m=>m.id===q.id);m.basePP??=m.pp;m.pp=m.basePP+u.ppBonusByMoveId[q.id];state.money-=q.cost;return true;}
export function migrateTeamcraftState(state,moves){for(const egg of state.nursery?.eggs||[])redirectInheritance(egg.inheritance);for(const u of [...(state.party||[]),...(state.reserve||[]),...(state.dead||[])])normalizeTeamcraftUnit(u,moves);const stock={};for(const [id,n]of Object.entries(state.moveScrolls||{})){const key=canonicalMoveId(id);stock[key]=(stock[key]||0)+n;}state.moveScrolls=stock;for(const q of state.rewardQueue||[])if(q.moveId)q.moveId=canonicalMoveId(q.moveId);return state;}
